import { Component } from '@angular/core';
import { Router } from '@angular/router';

@Component({
  selector: 'app-hero',
  standalone: true,
  template: `
    <section class="hero-section">
      <div class="container">
        <div class="hero-content">
          <h1 class="title title--hero">
            Your Digital Vision, <span class="title--accent">&lt;/&gt;</span> OUR CODE
          </h1>
          <p class="text text--lead">
            We turn your business ideas into powerful web applications with speed and the control you need.
          </p>
          <div class="hero-buttons">
            <button class="btn btn--primary" (click)="scrollToInquiryForm()">
              Start Your Project <span class="btn-arrow">→</span>
            </button>
            <button class="btn btn--secondary" (click)="goToPortfolio()">
              View Our Work
            </button>
          </div>
        </div>
      </div>
    </section>
  `,
  styles: [`
    .hero-section {
      background: linear-gradient(135deg, #f0fdf4 0%, #ecfdf5 100%);
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 2rem 0;
      position: relative;
      overflow: hidden;
    }

    .hero-section::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100"><defs><pattern id="grid" width="10" height="10" patternUnits="userSpaceOnUse"><path d="M 10 0 L 0 0 0 10" fill="none" stroke="%23a7f3d0" stroke-width="0.5" opacity="0.3"/></pattern></defs><rect width="100" height="100" fill="url(%23grid)"/></svg>');
      opacity: 0.5;
      z-index: 1;
    }

    .container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 1rem;
      position: relative;
      z-index: 2;
    }

    .hero-content {
      text-align: center;
      max-width: 800px;
      margin: 0 auto;
      animation: fadeInUp 0.8s ease-out;
    }

    .title--hero {
      font-family: 'Code Bold', monospace;
      font-weight: 700;
      font-size: 3.5rem;
      line-height: 1.1;
      margin-bottom: 1.5rem;
      color: #111827;
      letter-spacing: -0.02em;
    }

    .title--accent {
      color: #10b981;
      position: relative;
      display: inline-block;
      animation: pulse 2s infinite;
    }

    .text--lead {
      font-family: 'Coolvetica', sans-serif;
      font-weight: 600;
      font-size: 1.25rem;
      line-height: 1.6;
      color: #6b7280;
      margin-bottom: 2.5rem;
      max-width: 600px;
      margin-left: auto;
      margin-right: auto;
    }

    .hero-buttons {
      display: flex;
      gap: 1rem;
      justify-content: center;
      align-items: center;
      flex-wrap: wrap;
    }

    .btn {
      padding: 0.875rem 2rem;
      border: 2px solid transparent;
      border-radius: 0.5rem;
      font-family: 'Code Bold', monospace;
      font-weight: 700;
      font-size: 1rem;
      cursor: pointer;
      transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      position: relative;
      overflow: hidden;
      text-decoration: none;
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
    }

    .btn--primary {
      background: #10b981;
      color: #FFFFFF;
      border-color: #10b981;
    }

    .btn--primary:hover {
      background: #0d9488;
      border-color: #0d9488;
      transform: translateY(-2px);
      box-shadow: 0 8px 25px rgba(16, 185, 129, 0.3);
    }

    .btn--secondary {
      background: transparent;
      color: #10b981;
      border-color: #10b981;
    }

    .btn--secondary:hover {
      background: #10b981;
      color: #FFFFFF;
      transform: translateY(-2px);
      box-shadow: 0 8px 25px rgba(16, 185, 129, 0.3);
    }

    .btn:active {
      transform: translateY(0);
    }

    .btn-arrow {
      transition: transform 0.3s ease;
    }

    .btn:hover .btn-arrow {
      transform: translateX(4px);
    }

    /* Responsive Design */
    @media (min-width: 320px) {
      .title--hero {
        font-size: 2.5rem;
      }
      
      .text--lead {
        font-size: 1.125rem;
      }
      
      .hero-buttons {
        flex-direction: column;
        width: 100%;
      }
      
      .btn {
        width: 100%;
        justify-content: center;
      }
    }

    @media (min-width: 376px) {
      .title--hero {
        font-size: 2.75rem;
      }
    }

    @media (min-width: 768px) {
      .hero-section {
        min-height: 80vh;
        padding: 4rem 0;
      }
      
      .title--hero {
        font-size: 3rem;
      }
      
      .hero-buttons {
        flex-direction: row;
        width: auto;
      }
      
      .btn {
        width: auto;
      }
    }

    @media (min-width: 1024px) {
      .title--hero {
        font-size: 3.5rem;
      }
      
      .text--lead {
        font-size: 1.375rem;
      }
    }

    @media (min-width: 1440px) {
      .hero-section {
        min-height: 90vh;
      }
      
      .title--hero {
        font-size: 4rem;
      }
    }

    /* Animations */
    @keyframes fadeInUp {
      from {
        opacity: 0;
        transform: translateY(30px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    @keyframes pulse {
      0%, 100% {
        opacity: 1;
      }
      50% {
        opacity: 0.7;
      }
    }

    /* Focus states for accessibility */
    .btn:focus {
      outline: 2px solid #10b981;
      outline-offset: 2px;
    }

    /* Loading state */
    .btn:disabled {
      opacity: 0.6;
      cursor: not-allowed;
      transform: none;
    }
  `]
})
export class HeroComponent {
  constructor(private router: Router) {}

  scrollToInquiryForm() {
    const el = document.getElementById('inquiry-form');
    if (el) {
      el.scrollIntoView({ behavior: 'smooth' });
    }
  }

  goToPortfolio() {
    this.router.navigate(['/portfolio']);
  }
}
